use verus::prelude::*;

// create_row(v, i) returns a vector of the same length as v
// whose j-th entry is v[j] if j==i, and 0.0 otherwise.
#[requires(i < v.len())]
#[ensures(result.len() == v.len())]
#[ensures(forall(|j: usize| j < v.len() ==>
    (if j == i { result[j] == v[j] } else { result[j] == 0.0 })
))]
fn create_row(v: &Vec<f32>, i: usize) -> Vec<f32> {
    v.iter()
     .enumerate()
     .map(|(j, &val)| if j == i { val } else { 0.0 })
     .collect()
}

// diagflat(v) returns an n×n matrix (n = v.len()) whose
// (i, j)-entry is v[i] if i==j, and 0.0 otherwise.
#[ensures(result.len() == v.len())]
#[ensures(forall(|i: usize| i < v.len() ==> result[i].len() == v.len()))]
#[ensures(forall(|i: usize, j: usize| i < v.len() && j < v.len() ==>
    result[i][j] == (if i == j { v[i] } else { 0.0 })
))]
fn diagflat(v: Vec<f32>) -> Vec<Vec<f32>> {
    (0..v.len())
        .map(|i| create_row(&v, i))
        .collect()
}

